    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c]]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    outer = grid[r0][c0]
    counts = {}
    for r, c in cells:
        if grid[r][c] != outer:
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    if not counts:
        return [row[:] for row in grid]
    inner = max(counts, key=counts.get)
    inside = [(r,c) for r,c in cells if grid[r][c] == inner]
    ir0, ir1 = min(r for r,c in inside), max(r for r,c in inside)
    ic0, ic1 = min(c for r,c in inside), max(c for r,c in inside)
    dr0, dr1 = ir0-r0, r1-ir1
    dc0, dc1 = ic0-c0, c1-ic1
    out = [row[:] for row in grid]
    for r in range(max(0,r0-dr0), min(h,r1+dr1+1)):
        for c in range(max(0,c0-dc0), min(w,c1+dc1+1)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = inner
    return out
